POSTS = [
 dict(s="start-with-the-decision-not-the-venue", t="Start with the decision, not the venue", c="Event Strategy", d="2026-09-10", r=4, i=IM["cons"], ex="Before you book a room, decide what you want people to do differently afterwards.",
      b=["Most event briefs begin with a date and a venue. It works better to begin with a sentence: after this event, we want these people to have done this. A client signed, a partnership started, a team agreed on a plan.", "Once that sentence exists, most other choices get easier. It tells you who needs to be in the room, how long they should stay, and whether you need a stage at all or simply a long table and twelve chairs.", "It also gives you something to measure. If the goal was three follow-up meetings, count the follow-up meetings. That is a better report than attendance figures."]),
 dict(s="why-smaller-rooms-make-better-conversations", t="Why smaller rooms make better conversations", c="Executive Networking", d="2026-08-21", r=3, i=IM["net"], ex="A short guest list, a seated format and a follow-up plan do most of the work.",
      b=["Senior people rarely lack events to attend. What they lack is time, so the question they ask is whether the people in the room are worth meeting.", "A seated dinner for twenty usually does more than a reception for two hundred. Everyone talks to everyone, and nobody spends the evening looking over someone's shoulder.", "The work continues after the evening. A short, personal note within two days, with introductions where they make sense, is what turns a good dinner into a working relationship."]),
 dict(s="working-out-whether-an-event-paid-off", t="Working out whether an event paid off", c="Corporate Events", d="2026-07-02", r=4, i=IM["off"], ex="Agree what success looks like before the invitations go out, then keep the tracking simple.",
      b=["Return on an event is easy to argue about afterwards and hard to prove unless the measures are agreed beforehand. Decide them at the start, with the people who will judge the result.", "Pick a small number. Meetings booked, deals moved forward, partners introduced or feedback scores are usually enough. Collect them the same way every time.", "Then look at what the numbers say and change something for the next event. Most of the value in measuring is in that second step."]),

 dict(s="ai-in-the-room", t="AI in the room: where it helps an event and where it gets in the way", c="Technology", d="2026-09-28", r=5, i=IM["team"], ex="Useful for the people running an event, a poor substitute for the people attending it.",
      b=["AI is now part of most events teams' daily tools, whether or not anyone announced it. It drafts invitations, tidies guest lists, summarises feedback forms and turns a rough agenda into a clean one. Used like this it saves hours, and the hours go back into the parts of the job that need a person.", "It gets in the way when it sits between the host and the guest. An automated greeting, a generic follow-up or a matchmaking suggestion nobody has checked can make a senior guest feel like a record in a database. At an invitation-only dinner, that costs far more than the time it saved.", "A simple rule works well: let AI prepare, and let people decide and speak. Anything that carries your name to a guest should be read first by someone who knows that guest."]),
 dict(s="five-practical-ways-ai-can-save-an-events-team-time", t="Five practical ways AI can save an events team time", c="Technology", d="2026-09-17", r=4, i=IM["cons"], ex="Small, unglamorous uses that add up over a busy season.",
      b=["The useful applications are rarely the dramatic ones. They are small tasks that eat a week over a season: first drafts of invitations and reminders, summarising a long thread of supplier emails, turning notes from a planning call into an action list, translating a programme for an international audience, and sorting feedback comments into themes.", "Each of these produces a draft, not a finished product. Names, dates, figures and tone still need checking by someone who knows the event. Treat the output the way you would treat work from a new colleague: quick, helpful and not yet signed off.", "Be careful what you paste in. Guest lists and contracts contain other people's information, so check what your tools do with it, and what your own policies allow, before you use them."]),
 dict(s="why-in-person-still-matters", t="Why in-person still matters in a world of video calls", c="Industry Insights", d="2026-09-01", r=3, i=IM["net"], ex="Video is efficient for updates. Trust is still built in the same room.",
      b=["Video calls are very good at moving information. They are less good at the things that happen around the information: the quiet word before a session, the second coffee, the moment you realise the person next to you is dealing with the same problem.", "Those moments are why people still travel to meet. A room full of peers gives a leader something a call cannot, which is a sense of how others are thinking about the same decisions and the chance to ask a follow-up question straight away.", "That is also the argument for keeping events small, well hosted and worth the journey. If people are going to give up a day, the day should earn it."]),
 dict(s="how-to-choose-a-city-for-an-international-event", t="How to choose a city for an international event", c="Corporate Events", d="2026-08-10", r=5, i=IM["nyc"], ex="Flights, time zones and venues matter more than the postcard.",
      b=["A city can look right in a brochure and be hard on the day. Start with the practical questions. Where are most guests travelling from, and how many connections does that involve? Are there direct flights at sensible times? Does the time zone suit people joining remotely?", "Then look at venues. Major business cities usually have hotels with proper meeting space, restaurants with private rooms and a handful of distinctive spaces, but the good ones book months ahead, especially around large trade fairs and public holidays. Check the local calendar before you fix a date.", "Finally, think about the guests. Visa requirements, accessibility, dietary needs and local customs should shape the plan from the beginning, not arrive as problems in the final weeks."]),
 dict(s="what-makes-a-keynote-worth-sitting-through", t="What makes a keynote worth sitting through", c="Leadership", d="2026-07-28", r=4, i=IM["conf"], ex="A clear argument, a short running time and room for questions.",
      b=["The best keynotes make one argument and stick to it. The speaker knows what they want the room to think differently about, and every story and slide serves that point. If a talk can be summed up in a single sentence, it is usually a good one.", "Length matters too. Twenty tight minutes followed by real questions will beat forty minutes of material nobody asked for. Brief speakers on the audience, the time slot and what the previous session covered, so they do not repeat each other.", "As the host, protect the questions. A moderator who has read the talk in advance and prepared three good questions makes the speaker, and the session, better."]),
 dict(s="working-with-sponsors-without-an-advert", t="Working with sponsors without turning the day into an advert", c="Event Strategy", d="2026-07-14", r=4, i=IM["lights"], ex="Sponsors want visibility. Guests want a useful day. You can give both.",
      b=["Sponsors fund a lot of good events, and they are right to expect something in return. Problems start when that return is a series of product pitches the audience did not ask for.", "A better approach is to agree early what each sponsor can offer the guests: a practical session, a roundtable they host, or an introduction to someone relevant. Visibility follows from being useful, and sponsors tend to renew when their name is linked with a session people enjoyed.", "Put the rules in writing before the event, including speaking time, branding and any follow-up with guest details, so everyone knows where the lines are."]),
 dict(s="greener-events-without-the-gimmicks", t="Greener events without the gimmicks", c="Industry Insights", d="2026-06-19", r=4, i=IM["off"], ex="A few good decisions on travel, food and materials make most of the difference.",
      b=["Most of an event's environmental impact comes from three things: how people travel, what they eat, and how much is built, printed and thrown away. Start with those and you have covered most of it.", "Choose venues that are easy to reach by train or public transport, order food for the people who will actually attend, and design signage and staging that can be used again. None of this makes an event feel smaller.", "Be honest in how you describe it. Say what you changed and what you measured, and avoid big claims you cannot support."]),
 dict(s="advice-for-first-time-panellists", t="Advice for first-time panellists", c="Leadership", d="2026-06-05", r=3, i=IM["conf2"], ex="Prepare two points, listen to the others and keep your answers short.",
      b=["Being asked to join a panel is a good sign, and a slightly nerve-racking one. The preparation is simpler than it feels: decide on two points you want to make, and have one example for each.", "During the session, listen. The best panels sound like a conversation, so respond to what the previous speaker said rather than waiting for your turn to recite. Keep answers to about a minute and leave room for the others.", "Ask the moderator beforehand what the first question will be, and agree who will cover what so you do not all give the same answer."]),
 dict(s="looking-after-guest-data-at-your-event", t="Looking after guest data at your event", c="Technology", d="2026-05-22", r=4, i=IM["team"], ex="Collect what you need, say why, keep it safe and delete it when you are done.",
      b=["Every event collects personal information: names, email addresses, job titles, sometimes dietary needs. Treat it with the same care as the event itself, because guests notice when it is handled badly.", "Four habits cover the basics. Ask only for what you need. Tell people why you are asking and what will happen to it. Store it somewhere secure, with access limited to those who need it. Delete it when you no longer have a reason to keep it.", "The rules that apply depend on where your guests live and what you do with the data, so check with a qualified adviser rather than relying on a blog post, including this one."]),
]
