CITY = '<section><div class="wrap">' + head("Across the US, EMEA, and beyond") + '<div class="car" role="region" aria-roledescription="carousel" aria-label="Event and city photography"><div class="ctrack" tabindex="0">' + "".join(f'<div class="cs"><img src="{IM[k]}" alt="{"L1C — Level One Connect" if lg else "City skyline"}" loading="lazy" width="800" height="500">' + (f'<div class="cl"><img src="{LOGO_NAV}" alt="" width="{NW}" height="{NH}"></div>' if lg else "") + "</div>" for k, lg in SLIDES) + '</div><button class="cb2 cprev" type="button" aria-label="Previous photo">‹</button><button class="cb2 cnext" type="button" aria-label="Next photo">›</button></div></div></section>'
SEARCH = '<section class="sb"><div class="wrap"><form class="sbar" role="search" onsubmit="return false"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg><input id="es" type="search" placeholder="Search events by name, city or category" aria-label="Search events" autocomplete="off"></form><p id="ecount" class="mut" role="status" aria-live="polite"></p></div></section>'
